import{_ as s,c as i,o as a,a4 as e}from"./chunks/framework.BgUgRheH.js";const y=JSON.parse('{"title":"Defining Abilities: Best Practices","description":"","frontmatter":{},"headers":[],"relativePath":"define_abilities_best_practices.md","filePath":"define_abilities_best_practices.md","lastUpdated":1647344135000}'),n={name:"define_abilities_best_practices.md"},t=e('<h1 id="defining-abilities-best-practices" tabindex="-1">Defining Abilities: Best Practices <a class="header-anchor" href="#defining-abilities-best-practices" aria-label="Permalink to &quot;Defining Abilities: Best Practices&quot;">​</a></h1><h2 id="use-hash-conditions-as-much-as-possible" tabindex="-1">Use hash conditions as much as possible <a class="header-anchor" href="#use-hash-conditions-as-much-as-possible" aria-label="Permalink to &quot;Use hash conditions as much as possible&quot;">​</a></h2><h3 id="although-scopes-are-fine-for-fetching-they-pose-a-problem-when-authorizing-a-discrete-action" tabindex="-1">Although scopes are fine for fetching, they pose a problem when authorizing a discrete action. <a class="header-anchor" href="#although-scopes-are-fine-for-fetching-they-pose-a-problem-when-authorizing-a-discrete-action" aria-label="Permalink to &quot;Although scopes are fine for fetching, they pose a problem when authorizing a discrete action.&quot;">​</a></h3><p>For example, this declaration in Ability:</p><div class="language-ruby vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ruby</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">can </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:read</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Article</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Article</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.is_published</span></span></code></pre></div><p>causes this <code>CanCan::Error</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The can? and cannot? call cannot be used with a raw sql &#39;can&#39; definition.</span></span>\n<span class="line"><span>The checking code cannot be determined for :read #&lt;Article ..&gt;.</span></span></code></pre></div><p>A better way to define the same is:</p><div class="language-ruby vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ruby</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">can </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:read</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Article</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">is_published:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span></code></pre></div><h3 id="hash-conditions-are-dryer" tabindex="-1">Hash conditions are DRYer. <a class="header-anchor" href="#hash-conditions-are-dryer" aria-label="Permalink to &quot;Hash conditions are DRYer.&quot;">​</a></h3><p>By using hashes instead of blocks for all actions, you won&#39;t have to worry about translating blocks used for member controller actions (<code>:create</code>, <code>:destroy</code>, <code>:update</code>) to equivalent blocks for collection actions (<code>:index</code>, <code>:show</code>)—which require hashes anyway!</p><h3 id="hash-conditions-are-or-d-in-sql-giving-you-maximum-flexibility" tabindex="-1">Hash conditions are OR&#39;d in SQL, giving you maximum flexibility. <a class="header-anchor" href="#hash-conditions-are-or-d-in-sql-giving-you-maximum-flexibility" aria-label="Permalink to &quot;Hash conditions are OR&#39;d in SQL, giving you maximum flexibility.&quot;">​</a></h3><p>Every time you define an ability with <code>can</code>, each <code>can</code> chains together with OR in the final SQL query for that model.</p><p>So if, in addition to the <code>is_published</code> condition above, we want to allow authors to see their drafts:</p><div class="language-ruby vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ruby</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">can </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:read</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Article</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">author_id:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> @user.id, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">is_published:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span></span></code></pre></div><p>Then the final SQL would be:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `articles`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   `articles`</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `articles`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`is_published`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">OR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`articles`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`author_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 97</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AND</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `articles`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`is_published`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> )</span></span></code></pre></div><h3 id="for-complex-object-graphs-hash-conditions-accommodate-joins-easily" tabindex="-1">For complex object graphs, hash conditions accommodate <code>joins</code> easily. <a class="header-anchor" href="#for-complex-object-graphs-hash-conditions-accommodate-joins-easily" aria-label="Permalink to &quot;For complex object graphs, hash conditions accommodate `joins` easily.&quot;">​</a></h3><p>See <a href="./hash_of_conditions">Hash of Conditions Chapter</a>.</p><h3 id="give-permissions-don-t-take-them-away" tabindex="-1">Give permissions, don&#39;t take them away <a class="header-anchor" href="#give-permissions-don-t-take-them-away" aria-label="Permalink to &quot;Give permissions, don&#39;t take them away&quot;">​</a></h3><p>As suggested in this <a href="https://www.reddit.com/r/ruby/comments/6ytka8/refactoring_cancancan_abilities_brewing_bits/" target="_blank" rel="noreferrer">topic on Reddit</a> you should, when possible, give increasing permissions to your users.</p><p>CanCanCan increases permissions: it starts by giving no permissions to nobody and then increases those permissions depending on the user.</p><p>A properly written <code>ability.rb</code> looks like that:</p><div class="language-ruby vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ruby</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Ability</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  include</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> CanCan</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Ability</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> initialize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(user)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    can </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:read</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Post</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # start by defining rules for all users, also not logged ones</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> unless</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user.present?</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    can </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:manage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Post</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">user_id:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user.id </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># if the user is logged in can manage it&#39;s own posts</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    can </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:create</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Comment</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # logged in users can also create comments</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> unless</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user.manager? </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># if the user is a manager we give additional permissions</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    can </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:manage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Comment</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # like managing all comments in the website</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> unless</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user.admin?</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    can </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:manage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:all</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # finally we give all remaining permissions only to the admins</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  end</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">end</span></span></code></pre></div><p>following this good practice will help you to keep your permissions clean and more readable.</p><p>The risk of giving wrong permissions to the wrong users is also decreased.</p>',26),h=[t];function l(p,r,o,k,d,c){return a(),i("div",null,h)}const E=s(n,[["render",l]]);export{y as __pageData,E as default};
